command:
$ErrorActionPreference = 'Stop'
$branch = 'issue-588-dcoir-review-path-write-verification'
$expectedHead = 'eb01b68fd4fc25816e3dd369b2f2993372e32963'
function Invoke-Git([string[]]$GitArgs) {
  Write-Host "git $($GitArgs -join ' ')"
  $output = & git @GitArgs
  $code = $LASTEXITCODE
  if ($output) { $output | Out-Host }
  if ($code -ne 0) { throw "git failed with exit $($code): git $($GitArgs -join ' ')" }
}
$fetchRef = "refs/heads/" + $branch + ":refs/remotes/origin/" + $branch
Invoke-Git @('fetch', '--no-tags', 'origin', $fetchRef)
$remoteHead = (& git rev-parse "refs/remotes/origin/$branch").Trim()
if ($LASTEXITCODE -ne 0) { throw 'Unable to read remote branch head.' }
if ($remoteHead -ne $expectedHead) { throw "PR head drifted: expected $expectedHead got $remoteHead" }
Invoke-Git @('checkout', '--detach', "origin/$branch")
$env:PYTHONDONTWRITEBYTECODE = '1'
foreach ($name in @('DCOIR_GEMINI_API','DCOIR_OPENAI_API_KEY','DCOIR_OPENAI_PROJECT_ID','OPENAI_API_KEY')) {
  Remove-Item "Env:$name" -ErrorAction SilentlyContinue
}
Invoke-Git @('diff', '--check')
$configPath = '.github/dcoir_review/openrouter-pr-review-pareto.yml'
$commands = [System.Collections.Generic.List[string]]::new()
$inValidation = $false
foreach ($line in Get-Content -LiteralPath $configPath) {
  if ($line -eq 'validation_commands:') { $inValidation = $true; continue }
  if (-not $inValidation) { continue }
  if ($line -match '^  - (.+)$') { [void]$commands.Add($Matches[1]); continue }
  if ($line -match '^\S') { break }
}
if ($commands.Count -ne 61) { throw "Expected 61 governed validation commands, found $($commands.Count)." }
$python = (Get-Command python3 -ErrorAction SilentlyContinue)
if (-not $python) { $python = Get-Command python -ErrorAction Stop }
for ($i = 0; $i -lt $commands.Count; $i++) {
  $number = $i + 1
  $cmd = $commands[$i]
  Write-Host "=== Governed validation command $number/61: $cmd ==="
  if ($cmd -match '^python3 (\S+)$') {
    & $python.Source $Matches[1]
  } elseif ($cmd -match '^bash (\S+)$') {
    & bash $Matches[1]
  } elseif ($cmd -match '^pwsh -NoProfile -File (\S+) -AllowPowerShell7 -AllowEmpty$') {
    & pwsh -NoProfile -File $Matches[1] -AllowPowerShell7 -AllowEmpty
  } else {
    throw "Unexpected governed validation command shape at $($number): $cmd"
  }
  if ($LASTEXITCODE -ne 0) { throw "Governed validation command $number failed with exit $($LASTEXITCODE): $cmd" }
}
$status = @(& git status --porcelain)
if ($status.Count -ne 0) { throw "Worktree not clean after validation: $($status -join '; ')" }
Write-Host "PR #589 exact-head governed validation passed all 61 commands at $expectedHead."
